// Renders the page from four JSON files: league.json (who we are), snapshot.json
// and history.json (generated by scripts/update.py), prices.json and rules.json.

const COLORS = ['var(--brian)', 'var(--jess)', 'var(--emily)', 'var(--kevin)', '#f2994a', '#2d9cdb', '#f2c94c'];

const $ = (sel) => document.querySelector(sel);
const el = (tag, attrs = {}, ...children) => {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
        if (k === 'class') node.className = v;
        else if (k === 'style') node.style.cssText = v;
        else if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
        else node.setAttribute(k, v);
    }
    for (const c of children.flat()) {
        if (c == null) continue;
        node.append(c.nodeType ? c : document.createTextNode(String(c)));
    }
    return node;
};

const fmtDate = (iso) => {
    if (!iso) return 'TBA';
    const d = new Date(iso + 'T12:00:00');
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
};

async function load(name) {
    const res = await fetch(`data/${name}.json`, { cache: 'no-cache' });
    if (!res.ok) throw new Error(`${name}.json: ${res.status}`);
    return res.json();
}

function ptsCell(points) {
    const cls = points < 0 ? 'pts neg' : points === 0 ? 'pts zero' : 'pts';
    return el('td', { class: `num ${cls}` }, points === 0 ? '–' : points);
}

function renderMeta(snapshot, league) {
    $('#season').textContent = `Vulture Movies Fantasy League · ${league.season}`;
    const parts = [
        `Leaderboard updated ${snapshot.leaderboardUpdated || 'recently'}`,
        `${snapshot.totalTeams.toLocaleString()} teams`,
        `top score ${snapshot.topScore}`,
        `mirrored ${new Date(snapshot.fetchedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`,
    ];
    const meta = el('span', {}, parts.join(' · '));
    if (snapshot.fitMismatches) {
        meta.append(el('span', { class: 'warn' }, ` · per-movie fit is off on ${snapshot.fitMismatches} teams`));
    }
    $('#meta').replaceChildren(meta);
}

function renderStandings(members, snapshot, history) {
    const prev = history.length > 1 ? history[history.length - 2].teams : null;
    const cards = members.map((m) => {
        const t = snapshot.members[m.team];
        if (!t) {
            return el('div', { class: 'card', style: `--accent:${m.color}` },
                el('div', { class: 'who' }, m.name),
                el('div', { class: 'team' }, m.team),
                el('div', { class: 'note' }, 'Not found on the leaderboard'));
        }
        const before = prev && prev[m.team];
        let delta = null;
        if (before) {
            const d = t.score - before.score;
            delta = el('div', { class: `delta ${d > 0 ? 'up' : 'flat'}` }, d > 0 ? `+${d} since last update` : 'no change');
        }
        return el('div', { class: 'card', style: `--accent:${m.color}` },
            el('div', { class: 'who' }, m.name),
            el('div', { class: 'team' }, m.team),
            el('div', { class: 'score' }, t.score),
            el('div', { class: 'rank' }, `#${t.rank.toLocaleString()} of ${snapshot.totalTeams.toLocaleString()}`),
            delta);
    });
    $('#standings-cards').replaceChildren(...cards);
}

function renderChart(members, history) {
    const wrap = $('#chart');
    const entries = history
        .map((h) => ({ ...h, published: h.published || h.date }))
        .sort((a, b) => a.published.localeCompare(b.published));
    if (!entries.length) {
        wrap.replaceChildren(el('p', { class: 'note' }, 'No leaderboard history yet.'));
        return;
    }
    // Scoring began with the Oct. 2 weekend, so every team starts the season at zero.
    const start = { key: 'Season start', published: '2026-10-02', start: true, teams: Object.fromEntries(members.map((m) => [m.team, { score: 0 }])) };
    const weeks = [start, ...entries.filter((e) => e.published > start.published)];

    const W = 720, H = 300, L = 40, R = 150, T = 14, B = 28;
    const day = (iso) => Date.parse(iso + 'T12:00:00') / 86400000;
    const d0 = day(weeks[0].published), d1 = day(weeks[weeks.length - 1].published);
    const x = (iso) => L + ((day(iso) - d0) / Math.max(d1 - d0, 1)) * (W - L - R);
    const maxScore = Math.max(10, ...weeks.flatMap((w) => Object.values(w.teams).map((t) => t.score)));
    const step = [10, 20, 25, 50, 100, 200, 250, 500].find((s) => maxScore / s <= 6) || 1000;
    const top = Math.ceil(maxScore / step) * step;
    const y = (v) => T + (1 - v / top) * (H - T - B);

    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', 'Running totals by week');
    const s = (tag, attrs, text) => {
        const n = document.createElementNS(svgNS, tag);
        for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
        if (text != null) n.textContent = text;
        svg.append(n);
        return n;
    };

    for (let v = 0; v <= top; v += step) {
        s('line', { class: 'grid', x1: L, x2: W - R, y1: y(v), y2: y(v) });
        s('text', { class: 'axis', x: L - 6, y: y(v) + 4, 'text-anchor': 'end' }, v);
    }
    weeks.forEach((w) => {
        s('text', { class: 'axis', x: x(w.published), y: H - 8, 'text-anchor': 'middle' },
            w.start ? 'Start' : fmtDate(w.published));
    });

    // Labels at the right edge, nudged apart so tied or close teams stay legible.
    const ends = members
        .map((m) => ({ m, score: weeks[weeks.length - 1].teams[m.team]?.score }))
        .filter((e) => e.score != null)
        .sort((a, b) => b.score - a.score);
    let lastY = -Infinity;
    for (const e of ends) {
        e.ly = Math.max(y(e.score), lastY + 15);
        lastY = e.ly;
    }

    for (const m of members) {
        const pts = weeks.filter((w) => w.teams[m.team]).map((w) => ({ w, px: x(w.published), py: y(w.teams[m.team].score) }));
        if (!pts.length) continue;
        s('polyline', { class: 'line', stroke: m.color, points: pts.map((p) => `${p.px},${p.py}`).join(' ') });
        for (const p of pts) {
            const derived = !!p.w.source;
            const c = s('circle', { class: 'pt', cx: p.px, cy: p.py, r: 4, fill: derived ? 'var(--panel)' : m.color, stroke: derived ? m.color : 'var(--panel)' });
            const title = document.createElementNS(svgNS, 'title');
            title.textContent = `${m.name} · ${p.w.key}: ${p.w.teams[m.team].score}${derived ? ' (reconstructed)' : ''}`;
            c.append(title);
        }
        const end = ends.find((e) => e.m === m);
        s('text', { class: 'label', x: W - R + 10, y: end.ly + 4, fill: m.color }, `${m.name} ${end.score}`);
    }
    wrap.replaceChildren(svg);

}

function renderNews(snapshot) {
    const recap = $('#recap');
    if (snapshot.recap?.length) {
        // Paragraphs come from Vulture's hub page, reduced to text plus em/strong/a by the updater.
        recap.innerHTML = snapshot.recap.map((p) => `<p>${p}</p>`).join('');
        recap.append(el('p', { class: 'attribution' }, '— from the MFL hub page, ', el('a', { href: 'https://www.vulture.com/movies-league/' }, 'vulture.com/movies-league')));
    } else {
        recap.replaceChildren(el('p', { class: 'note' }, 'No recap found on the hub page this week.'));
    }
    const articles = snapshot.articles || [];
    const newsletters = articles.filter((a) => a.newsletter && a.body?.length);
    // Newsletter issues get their full text, newest one open, the rest click-to-expand.
    const issues = newsletters.map((a, i) => {
        const summary = el('summary', {},
            el('span', { class: 'when' }, a.date || ''),
            el('span', { class: 'title' }));
        summary.querySelector('.title').innerHTML = a.title;
        const body = el('div', { class: 'body' });
        // Paragraphs are Vulture's own markup, reduced to text plus em/strong/a/br by the updater.
        body.innerHTML = a.body.map((b) => `<${b.tag}>${b.html}</${b.tag}>`).join('');
        body.append(el('p', { class: 'attribution' }, '— ', el('a', { href: a.url }, 'read on vulture.com')));
        const d = el('details', { class: 'newsletter' }, summary, body);
        if (i === 0) d.open = true;
        return d;
    });
    $('#newsletters').replaceChildren(...issues);
    $('#newsletters-head').hidden = issues.length === 0;

    const rest = articles.filter((a) => !newsletters.includes(a));
    const items = rest.map((a) => {
        const li = el('li', {},
            el('span', { class: 'when' }, a.date || ''),
            el('a', { href: a.url }),
            a.newsletter ? el('span', { class: 'tag' }, 'newsletter') : null,
            a.teaser ? el('span', { class: 'teaser' }) : null);
        // Title and teaser are Vulture's own markup, reduced to em/strong/a by the updater.
        li.querySelector('a').innerHTML = a.title;
        if (a.teaser) li.querySelector('.teaser').innerHTML = a.teaser;
        return li;
    });
    $('#articles').replaceChildren(...items);
    $('#articles-head').hidden = items.length === 0;
}

function renderRosters(members, snapshot, prices) {
    const cards = members.map((m) => {
        const t = snapshot.members[m.team];
        if (!t) return null;
        const rows = [...t.roster]
            .sort((a, b) => b.points - a.points || a.title.localeCompare(b.title))
            .map((r) => {
                const p = prices[r.title];
                return el('tr', {},
                    el('td', {},
                        r.title,
                        p && !p.boxOfficeEligible ? el('span', { class: 'tag nobo', title: 'Released before Oct 2 — no box-office points' }, 'no BO') : null),
                    el('td', { class: 'num price' }, p ? `$${p.price}` : '—'),
                    ptsCell(r.points));
            });
        const spent = t.roster.reduce((s, r) => s + (prices[r.title]?.price || 0), 0);
        rows.push(el('tr', { class: 'footer' },
            el('td', {}, 'Spent'),
            el('td', { class: 'num' }, `$${spent}`),
            el('td', { class: 'num' }, t.score)));
        return el('div', { class: 'roster', style: `--accent:${m.color}` },
            el('div', { class: 'head' },
                el('div', {}, el('span', { class: 'who' }, m.name), el('span', { class: 'team' }, m.team)),
                el('div', { class: 'total' }, t.score)),
            el('table', {},
                el('thead', {}, el('tr', {}, el('th', {}, 'Movie'), el('th', { class: 'num' }, 'Price'), el('th', { class: 'num' }, 'Pts'))),
                el('tbody', {}, rows)));
    });
    $('#roster-cards').replaceChildren(...cards.filter(Boolean));
}

function renderLeague(members, snapshot, league) {
    const ours = new Map(members.map((m) => [m.team, m]));
    const inLeague = snapshot.officialLeague;
    const notListed = members.filter((m) => !inLeague.some((t) => t.team === m.team));
    $('#league-note').replaceChildren(
        league.officialLeagueNote, ' ',
        notListed.length ? `Not in this filter on Vulture: ${notListed.map((m) => `${m.name} (${m.team})`).join(', ')}.` : '');
    const rows = inLeague.map((t, i) => {
        const m = ours.get(t.team);
        return el('tr', { style: m ? `--accent:${m.color}` : '' },
            el('td', { class: 'num' }, i + 1),
            el('td', {}, t.team, m ? el('span', { class: 'tag us' }, m.name) : el('span', { class: 'tag shared' }, 'other group')),
            el('td', { class: 'num' }, `#${t.rank.toLocaleString()}`),
            el('td', { class: 'num pts' }, t.score));
    });
    $('#league-table tbody').replaceChildren(...rows);
}

function renderMovies(members, snapshot, prices) {
    const owners = new Map();
    for (const m of members) {
        const t = snapshot.members[m.team];
        if (!t) continue;
        for (const r of t.roster) {
            if (!owners.has(r.title)) owners.set(r.title, []);
            owners.get(r.title).push(m);
        }
    }
    const all = Object.entries(snapshot.movies).map(([title, v]) => ({
        title,
        points: v.points,
        drafted: v.drafted,
        price: prices[title]?.price ?? null,
        eligible: prices[title]?.boxOfficeEligible ?? true,
        owners: owners.get(title) || [],
    }));

    const search = $('#movie-search');
    const onlyOurs = $('#only-ours');
    const onlyScoring = $('#only-scoring');

    const draw = () => {
        const q = search.value.trim().toLowerCase();
        const rows = all
            .filter((m) => !onlyOurs.checked || m.owners.length)
            .filter((m) => !onlyScoring.checked || m.points !== 0)
            .filter((m) => !q || m.title.toLowerCase().includes(q))
            .sort((a, b) => b.points - a.points || b.drafted - a.drafted || a.title.localeCompare(b.title))
            .map((m) => el('tr', {},
                el('td', {}, m.title, m.eligible ? null : el('span', { class: 'tag nobo' }, 'no BO')),
                el('td', {}, el('span', { class: 'owners' },
                    ...m.owners.map((o) => el('span', { class: 'dot', style: `--accent:${o.color}`, title: o.name })))),
                el('td', { class: 'num price' }, m.price != null ? `$${m.price}` : '—'),
                ptsCell(m.points),
                el('td', { class: 'num price' }, m.price && m.points ? (m.points / m.price).toFixed(1) : '–'),
                el('td', { class: 'num price' }, m.drafted.toLocaleString())));
        $('#movie-table tbody').replaceChildren(...rows);
    };
    search.addEventListener('input', draw);
    onlyOurs.addEventListener('change', draw);
    onlyScoring.addEventListener('change', draw);
    draw();
}

function bandTable(title, sub, rows, label) {
    return el('div', { class: 'table-wrap' },
        el('table', {},
            el('caption', {}, title, el('span', { class: 'sub' }, sub)),
            el('thead', {}, el('tr', {}, el('th', {}, label), el('th', { class: 'num' }, 'Pts'))),
            el('tbody', {}, rows.map((r) => el('tr', {}, el('td', {}, r[0]), ptsCell(r[1]))))));
}

function renderRules(rules) {
    $('#rules-basics').replaceChildren(...rules.basics.map((b) => el('li', {}, b)));
    const bo = rules.boxOffice;
    const boRows = [[`Every $1M domestic`, bo.perMillion], ...bo.bonuses.map((b) => [`Clears $${b.threshold}M`, b.points]), ['Each week at No. 1', bo.numberOnePerWeek]];
    $('#rules-grid').replaceChildren(
        bandTable('Box office', bo.basis, boRows, 'Milestone'),
        bandTable('Metacritic', `Awarded ${fmtDate(rules.metacritic.awardedOn)}. ${rules.metacritic.note}`, rules.metacritic.bands.map((b) => [b.range, b.points]), 'Metascore'),
        bandTable('Letterboxd', `Awarded ${fmtDate(rules.letterboxd.awardedOn)}. ${rules.letterboxd.note}`, rules.letterboxd.bands.map((b) => [b.range, b.points]), 'Avg rating'),
    );

    const today = new Date().toISOString().slice(0, 10);
    const dated = rules.awards.filter((a) => a.date).sort((a, b) => a.date.localeCompare(b.date));
    const undated = rules.awards.filter((a) => !a.date);
    const next = dated.find((a) => a.date >= today);
    const rows = [...dated, ...undated].map((a) => el('tr', { class: a === next ? 'next' : a.date && a.date < today ? 'past' : '' },
        el('td', { class: 'when' }, fmtDate(a.date)),
        el('td', {}, a.event, el('span', { class: 'tag' }, a.kind)),
        el('td', { class: 'cats' }, ...a.tiers.flatMap((t, i) => [i ? el('br') : null, el('strong', {}, `${t.points}: `), t.categories]))));
    $('#awards-table tbody').replaceChildren(...rows);
}

function renderFooter(league, snapshot) {
    const l = league.links;
    $('#footer').replaceChildren(
        el('a', { href: l.hub }, 'MFL hub & official leaderboard'), ' · ',
        el('a', { href: l.draftGuide }, 'Draft guide'), ' · ',
        el('a', { href: l.officialRules }, 'Official rules'), ' · ',
        el('a', { href: l.oscarPicks }, 'Oscar picks'),
        el('br'),
        'Data is pulled from Vulture’s published leaderboard JSON; nothing here is official.');
}

async function main() {
    try {
        const [league, snapshot, history, prices, rules] = await Promise.all(
            ['league', 'snapshot', 'history', 'prices', 'rules'].map(load));
        const members = league.members.map((m, i) => ({ ...m, color: COLORS[i % COLORS.length] }));
        members.sort((a, b) => (snapshot.members[b.team]?.score ?? -1) - (snapshot.members[a.team]?.score ?? -1));
        renderMeta(snapshot, league);
        renderStandings(members, snapshot, history);
        renderChart(members, history);
        renderNews(snapshot);
        renderRosters(members, snapshot, prices);
        renderLeague(members, snapshot, league);
        renderMovies(members, snapshot, prices);
        renderRules(rules);
        renderFooter(league, snapshot);
    } catch (err) {
        $('#meta').textContent = `Could not load data: ${err.message}`;
        console.error(err);
    }
}

main();
